                <TimelineTime dateTime={new Date(deploy.time).toISOString()}>
                  {formatDayClock(deploy.time)}
                </TimelineTime>
                <TimelineDescription className="text-xs">
                  {deploy.author}
                </TimelineDescription>
              </TimelineItem>
            );
          })}
        </Timeline>
      </CardContent>
    </Card>
  );
}

export type Range = "1h" | "6h" | "24h";

export interface Point {
  time: number;
  requests: number;
  errorRate: number;
  p50: number;
  p95: number;
  p99: number;
  apdex: number;
}

export type ServiceStatus = "healthy" | "degraded" | "recovering";

export interface Service {
