const minute = 60_000;
const step = 5 * minute;
export const now = Date.UTC(2026, 9, 31, 11, 5);
const total = (2 * 1_440) / 5;

const at = (hours: number, minutes: number, day = 31) =>
  Date.UTC(2026, 9, day, hours, minutes);

