const clock = new Intl.DateTimeFormat("en-GB", {
  hour: "2-digit",
  minute: "2-digit",
  hour12: false,
  timeZone: "UTC",
});
const dayClock = new Intl.DateTimeFormat("en-GB", {
  month: "short",
  day: "numeric",
  hour: "2-digit",
  minute: "2-digit",
  hour12: false,
  timeZone: "UTC",
});

export const formatClock = (time: number) => clock.format(time);
export const formatDayClock = (time: number) =>
  time >= at(0, 0) ? `Today, ${clock.format(time)}` : dayClock.format(time);

const count = new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 });
const compact = new Intl.NumberFormat("en-US", {
  notation: "compact",
  maximumFractionDigits: 1,
});

export const formatCount = (value: number) => count.format(value);
export const formatCompact = (value: number) => compact.format(value);

const percent = (digits: number) =>
  new Intl.NumberFormat("en-US", {
    style: "percent",
    minimumFractionDigits: digits,
    maximumFractionDigits: digits,
  });
const percentFine = percent(2);
const percentCoarse = percent(1);

export function formatRate(value: number) {
  return (value < 0.01 ? percentFine : percentCoarse).format(value);
}

export function formatMs(value: number) {
  return value >= 1_000
    ? `${(value / 1_000).toFixed(value >= 10_000 ? 0 : 2)} s`
    : `${count.format(value)} ms`;
}

"use client";

import { PulseIcon } from "@phosphor-icons/react";
import { useMemo, useState } from "react";
